constraints:
1 ≤ N ≤ 10^{5}
1 ≤ Node Data ≤ 10^{5}

expected time complexity: O(NlogN)
expected auxiliary space: O(N).

standard_solution_code:
from collections import defaultdict

class Solution:

	def topView(self, root):
		mp = defaultdict(list)

		def traversal(node, x, y, mp):
			if node is None:
				return
			traversal(node.left, x - 1, y + 1, mp)
			traversal(node.right, x + 1, y + 1, mp)
			mp[x, y].append(node.data)
		traversal(root, 0, 0, mp)
		x = []
		i = {}
		for (k, v) in sorted(mp.items()):
			if k[0] not in i:
				i[k[0]] = 1
				x.append(v[0])
		return x
